-><!-- wp:atomic-wind/box {\"className\":\"flex flex-col justify-center gap-6 p-10 md:p-12\"} --><div class=\"wp-block-atomic-wind-box flex flex-col justify-center gap-6 p-10 md:p-12\"><!-- wp:atomic-wind/text {\"tagName\":\"h3\",\"className\":\"text-2xl font-bold tracking-tight text-slate-900 m-0\"} --><h3 class=\"wp-block-atomic-wind-text text-2xl font-bold tracking-tight text-slate-900 m-0\" data-rich-text=\"\">Get on the list</h3><!-- /wp:atomic-wind/text --><!-- wp:atomic-wind/box {\"className\":\"w-full\"} --><div class=\"wp-block-atomic-wind-box w-full\"><!-- wp:themeisle-blocks/form {\"submitLabel\":\"Join the waitlist\",\"submitStyle\":\"full\",\"id\":\"wp-block-themeisle-blocks-form-a7b8c9d0\",\"optionName\":\"2b4d6f8013579bdf2468ace013579bdf2468ace0_a7b8c9d0\",\"labelColor\":\"#0f172a\",\"labelFontSize\":\"13px\",\"inputBackgroundColor\":\"#f8fafc\",\"inputColor\":\"#0f172a\",\"inputBorderColor\":\"#e2e8f0\",\"inputBorderWidth\":1,\"inputBorderRadius\":{\"top\":\"12px\",\"right\":\"12px\",\"bottom\":\"12px\",\"left\":\"12px\"},\"inputPadding\":{\"top\":\"14px\",\"right\":\"16px\",\"bottom\":\"14px\",\"left\":\"16px\"},\"inputFontSize\":\"15px\",\"submitBackgroundColor\":\"#4f46e5\",\"submitBackgroundColorHover\":\"#4338ca\",\"submitColor\":\"#ffffff\",\"submitColorHover\":\"#ffffff\",\"submitFontSize\":\"15px\",\"buttonPadding\":{\"top\":\"15px\",\"right\":\"30px\",\"bottom\":\"15px\",\"left\":\"30px\"},\"submitMessageColor\":\"#0f172a\"} --><div id=\"wp-block-themeisle-blocks-form-a7b8c9d0\" class=\"wp-block-themeisle-blocks-form\" data-option-name=\"2b4d6f8013579bdf2468ace013579bdf2468ace0_a7b8c9d0\"><form class=\"otter-form__container\"><!-- wp:themeisle-blocks/form-input {\"id\":\"wp-block-themeisle-blocks-form-input-b8c9d0e1\",\"type\":\"text\",\"label\":\"Full name\",\"placeholder\":\"Jane Doe\",\"isRequired\":true,\"labelColor\":\"#0f172a\"} --><div id=\"wp-block-themeisle-blocks-form-input-b8c9d0e1\" class=\"wp-block-themeisle-blocks-form-input\">